value.Problema_Detectado:
={{ (() => { 
    try { 
        let textoIA = $('Clasificador de pagina Web').item?.json?.output || $('Clasificador de Leads').item?.json?.output || ""; 
        let jsonLimpio = textoIA.substring(textoIA.indexOf('{'), textoIA.lastIndexOf('}') + 1);
        let listaProblemas = JSON.parse(jsonLimpio).problemas_prioritarios;

        // Extraemos solo el texto del problema y los unimos con un salto de línea
        return listaProblemas.map(p => "• " + p.problema).join('\n'); 
    } catch(e) { 
        return 'No se detectaron problemas'; 
    } 
})() }}

